{"status":"candidate","chosen_option":"prefix-residue-count","assumptions":["The checker accepts C++17.","A signed 64-bit integer is available for the answer and prefix residues."],"observations":[{"statement":"Equal prefix-sum residues modulo k identify contiguous subarrays whose sums are divisible by k; the frequency map stores prior residues.","source_ids":["task"]},{"statement":"The count can reach 20000100000, so the implementation uses a 64-bit accumulator.","source_ids":["task"]},{"statement":"The supplied examples require outputs 0 and 21, respectively.","source_ids":["public1","public2"]}],"artifact":{"code":"#include <iostream>
#include <unordered_map>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long k;
    if (!(cin >> n >> k)) return 0;

    unordered_map<long long, long long> frequency;
    frequency.reserve(static_cast<size_t>(n) * 2 + 1);
    frequency[0] = 1;

    long long residue = 0;
    long long answer = 0;
    for (int i = 0; i < n; ++i) {
        long long value;
        cin >> value;
        residue = (residue + value % k) % k;
        if (residue < 0) residue += k;
        answer += frequency[residue];
        ++frequency[residue];
    }

    cout << answer << '\n';
    return 0;
}
